// === Tab: mySketch ===
// Simple illustration of 3D Particles in a Box
// Doug L. James, Sept 2020, http://graphics.stanford.edu/~djames

let H = 100; // box half width in each dimension
let NPARTICLES = 100;
let particles = [];
let easycam;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	easycam = createEasyCam();
	document.oncontextmenu = () => false;

	// CREATE PARTICLES:
	for (let k = 0; k < NPARTICLES; k++) {
		let r   = random(H / 10);
		let pos = createVector(random(-H+r, H-r), random(-H+r, H-r), random(-H+r, H-r));
		let vel = createVector(random(-1, 1), random(-1, 1), random(-1, 1)).mult(0.1);
		let col = color(random(40,255), random(40,255), random(40,255));
		let pk  = new Particle(pos, vel, r, col);
		particles.push(pk);
	}
}

function draw() {
	background(0);
	lights();
	noStroke();

	computeForces();

	let dt = deltaTime/100; // small timesteps
	for (let particle of particles) {
		// Update velocity:
		particle.updateVel(dt);

		// Filter velocity, e.g., collisions:
		bounceParticleOffWalls(particle);

		// Update position:
		particle.updatePos(dt);

		particle.draw();
	}

	noFill();
	stroke("gray");
	box(2 * H);
}

function computeForces()
{
	// Use camera for gravity vector:
	let g = easycam.getUpVector(createVector(0,0,0));// Vec3

	// ZERO OUT PREVIOUS FORCES & APPLY GRAVITY:
	for(let particle of particles) {
		particle.f.set(g);
		particle.f.mult(particle.mass);

	// APPLY INTER-PARTICLE REPULSION:
	//	for(let particle of particles) 
		//particle.f.set(0,0,0);
	}
}

function epsN() {
	return 0.7;
}

function epsT() {
	return 0.9;
}

// Filter velocity if outside box(H) and moving further
function bounceParticleOffWalls(A) {
	let R = A.r;

	// Boundary reflection (only if outside box AND still moving outward):
	if (abs(A.pos.x) + R > H && A.vel.x*A.pos.x > 0) {
		A.vel.x *= -epsN();
		A.vel.y *=  epsT();
		A.vel.z *=  epsT();
	}
	if (abs(A.pos.y) + R > H && A.vel.y*A.pos.y > 0) {
		A.vel.x *=  epsT();
		A.vel.y *= -epsN();
		A.vel.z *=  epsT();
	}
	if (abs(A.pos.z) + R > H && A.vel.z*A.pos.z > 0) {
		A.vel.x *=  epsT();
		A.vel.y *=  epsT();
		A.vel.z *= -epsN();
	}
}

// Spherical particle
class Particle {
	constructor(position, velocity, r, color) {
		this.pos = position;
		this.vel = velocity;
		this.r   = r;
		this.c   = color;
		this.f   = createVector(0,0,0);// force accumulator for updateVel
		this.mass = 4.0/3.0*PI*pow(r,3) / 1000;
	}

	// Timestep velocity by integrating forces:
	updateVel(dt) {
		// Compute dv = dt*acceleration in temp f:
		let dv = this.f.mult(dt/this.mass); // dv = dt*a = dt*f/m
		this.vel.add(dv);// v += dv
		this.f.set(0,0,0); // 
	}

	// Timestep position:
	updatePos(dt) {
		this.pos.x += dt * this.vel.x;
		this.pos.y += dt * this.vel.y;
		this.pos.z += dt * this.vel.z;
	}

	draw() {
		push();
		translate(this.pos);
		fill(this.c);
		sphere(this.r);
		pop(); // removes the translate transformation
	}
}

